function App() {
  const [on, setOn] = useState(false);
  return (
    <div style={{ fontFamily: 'system-ui', padding: 16 }}>
      <h2>{on ? 'ON' : 'OFF'}</h2>
      <button onClick={() => setOn(o => !o)}>Toggle</button>
    </div>
  );
}

