function App() {
  const [items, setItems] = useState(['a']);
  const add = () => setItems(prev => [...prev, 'x']);
  return (
    <div style={{ fontFamily: 'system-ui', padding: 16 }}>
      <button onClick={add}>Add</button>
      <ul>{items.map((i, idx) => <li key={idx}>{i}</li>)}</ul>
    </div>
  );
}

